import{_ as p,a0 as l,w as o,s as r,ao as d,I as i,x as t,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"Bash 中使用控制运算符连接命令 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 中使用控制运算符连接命令 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 中使用控制运算符连接命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 中使用控制运算符连接命令 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181121 Coupled commands with control operators in Bash","title":"Bash 中使用控制运算符连接命令","tag":"201812","desc":""},"relativePath":"201812/20181121 Coupled commands with control operators in Bash.md","filePath":"[post].md"}'),c={name:"201812/20181121 Coupled commands with control operators in Bash.md"};function h(u,s,m,g,k,b){const e=l("Link");return o(),r("div",null,[s[18]||(s[18]=d(`<h1 id="bash-中使用控制运算符连接命令" tabindex="-1">Bash 中使用控制运算符连接命令 <a class="header-anchor" href="#bash-中使用控制运算符连接命令" aria-label="Permalink to “Bash 中使用控制运算符连接命令”">​</a></h1><blockquote><p>在命令行中，使用控制运算符为复合命令添加逻辑。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/osdc-lead-yearbook-best-couple.png?itok=a_99oCdE" alt=""></p><p>经常会使用一些简单的复合指令，比如说在一个命令行中连接几个命令。这些命令使用分号分隔，表示一个命令结束。为了在一个命令行中创建一系列简单的 shell 命令，只需要使用分号把每一条命令分隔开，就像下面这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command1 ; command2 ; command3 ; command4 ;</span></span></code></pre></div><p>最后一个分号你可以不用添加，因为当你按下回车键时就表示一个命令的结束，但是为了和其它的保持一致，还是建议加上比较好。</p><p>所有的命令执行都没有什么问题 —— 只要没有什么意外发生。但是当出问题时到底发生了什么呢？我们可以预测，并且通过 Bash 中内置的 <code>&amp;&amp;</code> 和 <code>||</code> 运算符跟踪这些错误。这两个控制运算符提供了一些流控制，可以让我们改变代码执行队列的顺序。分号和换行符也被认为是 Bash 的控制运算符。</p><p><code>&amp;&amp;</code> 运算符意义简单来说就是“如果 <code>command1</code> 执行成功，就接着执行 <code>command2</code>。”如果 <code>command1</code> 因为任何原因执行失败，那么 <code>command2</code> 将不执行。这个语法看下来像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command1 &amp;&amp; command2</span></span></code></pre></div><p>这样写是允许的，因为每一个命令都会返回一个值（RC）给 shell 来表示这个命令在执行的过程中是否执行成功或者失败。通常，返回值是 <code>0</code> 表示成功，而一个正数值表示不同种类的错误。有一些系统管理工具仅仅返回一个 <code>1</code> 来表示所有的错误，但是也有很多工具使用其它的正数的返回值来表示各种类型错误。</p><p>我们可以很容易的使用脚本来检查 shell 变量 <code>$?</code>，可以通过命令列表中的下一个命令，或者可以直接使用系统管理工具检查。我们一起来看这些返回值。运行一个简单的命令然后立即检查它的返回值，这个返回值始终是属于最后一个运行的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ ll ; echo &quot;RC = $?&quot;</span></span>
<span class="line"><span>total 284</span></span>
<span class="line"><span>-rw-rw-r--  1 student student   130 Sep 15 16:21 ascii-program.sh</span></span>
<span class="line"><span>drwxrwxr-x  2 student student  4096 Nov 10 11:09 bin</span></span>
<span class="line"><span>&lt;snip&gt;</span></span>
<span class="line"><span>drwxr-xr-x. 2 student student  4096 Aug 18 10:21 Videos</span></span>
<span class="line"><span>RC = 0</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p>这个返回值是 <code>0</code>，表示这个命令执行成功了。现在尝试使用同样的命令在一些我们没有权限的目录上。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ ll /root ; echo &quot;RC = $?&quot;</span></span>
<span class="line"><span>ls: cannot open directory &#39;/root&#39;: Permission denied</span></span>
<span class="line"><span>RC = 2</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div>`,14)),i("p",null,[s[1]||(s[1]=t("这个返回值的含义可以在 ",-1)),a(e,{href:"http://man7.org/linux/man-pages/man1/ls.1.html"},{default:n(()=>[...s[0]||(s[0]=[t("ls 命令的 man 页面",-1)])]),_:1}),s[2]||(s[2]=t(" 中找到。",-1))]),s[19]||(s[19]=d(`<p>现在我们来试试 <code>&amp;&amp;</code> 这个控制运算符，因为它也可能会被用在一个命令行程序中。我们将从一个简单的示例开始：创建一个新目录，如果创建成功就在这个目录中创建一个文件。</p><p>我们需要一个目录可以创建其它的目录。首先，在你的家目录中创建一个临时的目录用来做测试。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ cd ; mkdir testdir</span></span></code></pre></div><p>在 <code>~/testdir</code> 中新建一个目录，这也应该是一个空目录，因为是你刚刚创建的，然后创建一个新的空文件在这个新目录中。下面的命令可以做这些事情。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ mkdir ~/testdir/testdir2 &amp;&amp; touch ~/testdir/testdir2/testfile1</span></span>
<span class="line"><span>[student@studentvm1 ~]$ ll ~/testdir/testdir2/</span></span>
<span class="line"><span>total 0</span></span>
<span class="line"><span>-rw-rw-r-- 1 student student 0 Nov 12 14:13 testfile1</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p>我们看到一切都运行得很好，因为 <code>testdir</code> 目录是访问且可写的。然后我们改变 <code>testdir</code> 目录的权限，让用户 <code>student</code> 不再具有访问的权限。操作如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ chmod 076 testdir ; ll | grep testdir</span></span>
<span class="line"><span>d---rwxrw-. 3 student student  4096 Nov 12 14:13 testdir</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p>在长列表（<code>ll</code>）命令后面使用 <code>grep</code> 命令来列出 <code>testdir</code> 目录。你可以看到用户 <code>student</code> 不再有 <code>testdir</code> 目录的访问权限。现在我们像之前一样运行同样的命令，但是在 <code>testdir</code> 目录中创建的是一个不同的目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ mkdir ~/testdir/testdir3 &amp;&amp; touch ~/testdir/testdir3/testfile1</span></span>
<span class="line"><span>mkdir: cannot create directory ‘/home/student/testdir/testdir3’: Permission denied</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p>尽管我们也同样得到了一个错误的消息，但 <code>&amp;&amp;</code> 控制运算符阻止了 <code>touch</code> 命令的运行，因为在创建 <code>testdir3</code> 目录的时候发生了错误。通过这种复合的流控制可以阻止一些错误的发生使事情变乱。但是这样看起来变得稍微复杂了一些。</p><p><code>||</code> 控制运算符允许添加另一个命令，这个命令在初始程序语句返回值大于 0 时执行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ mkdir ~/testdir/testdir3 &amp;&amp; touch ~/testdir/testdir3/testfile1 || echo &quot;An error occurred while creating the directory.&quot;</span></span>
<span class="line"><span>mkdir: cannot create directory ‘/home/student/testdir/testdir3’: Permission denied</span></span>
<span class="line"><span>An error occurred while creating the directory.</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p>当我们使用 <code>&amp;&amp;</code> 和 <code>||</code> 控制运算符时，使用流控制的复合命令的语法格式通常是下面这样的形式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>preceding commands ; command1 &amp;&amp; command2 || command3 ; following commands</span></span></code></pre></div><p>使用控制运算符的复合命令可以在其它命令之前或者之后，这些和控制运算符流控制有关系，但是不受控制运算符流控制的影响。如果不考虑复合命令的流控制中发生的任何事情那么所有的命令都将执行。</p><p>当程序出问题时，这些流控制运算符使得在命令中处理出错和通知我们变得更有效率。我直接在命令行中使用它们，也在脚本中使用。</p><p>你可以以 root 用户的身份来删除这个目录和它里面的内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@studentvm1 ~]# rm -rf /home/student/testdir</span></span></code></pre></div><p>你是怎样使用 Bash 控制运算符的呢？在评论区中告诉我们。</p><hr>`,20)),i("p",null,[s[4]||(s[4]=t("via: ",-1)),a(e,{href:"https://opensource.com/article/18/11/control-operators-bash-shell"},{default:n(()=>[...s[3]||(s[3]=[t("https://opensource.com/article/18/11/control-operators-bash-shell",-1)])]),_:1})]),i("p",null,[s[9]||(s[9]=t("作者：",-1)),a(e,{href:"https://opensource.com/users/dboth"},{default:n(()=>[...s[5]||(s[5]=[t("David Both",-1)])]),_:1}),s[10]||(s[10]=t(" 选题：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[6]||(s[6]=[t("lujun9972",-1)])]),_:1}),s[11]||(s[11]=t(" 译者：",-1)),a(e,{href:"https://github.com/Jamskr"},{default:n(()=>[...s[7]||(s[7]=[t("Jamskr",-1)])]),_:1}),s[12]||(s[12]=t(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[8]||(s[8]=[t("wxy",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=t("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[13]||(s[13]=[t("LCTT",-1)])]),_:1}),s[16]||(s[16]=t(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:n(()=>[...s[14]||(s[14]=[t("Linux中国",-1)])]),_:1}),s[17]||(s[17]=t(" 荣誉推出",-1))])])}const y=p(c,[["render",h]]);export{v as __pageData,y as default};
